static void update_trail(void) {
160→    uint8_t i;

    /* Shift history toward the tail so index 0 is the freshest afterglow. */
    for (i = TRAIL_LENGTH - 1u; i > 0u; --i) {
        trail_x[i] = trail_x[i - 1u];
        trail_y[i] = trail_y[i - 1u];
