            move_sprite((uint8_t)(TRAIL_SPRITE_BASE + i), 0u, 0u);
        }
180→    }
}

static void initialize_video(void) {
    uint8_t i;

    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
190→    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    /* Dimmer palette so trail sprites read as a soft neon afterglow. */
    OBP1_REG = 0x90u;
    NR52_REG = 0u;

200→    /*
     * Bit 4 remains clear so background tile IDs $80-$FF use the signed
     * $8800 tile-data region. SHOW_BKG, SHOW_SPRITES, and DISPLAY_ON below
     * turn this into the original final LCDC value, $C3.
