    LCDC_REG = 0x40u;

    set_bkg_data(0x80u, BREAKOUT_TILE_COUNT, breakout_tile_data);
    set_bkg_tiles(
        0u,
210→        0u,
        BREAKOUT_MAP_WIDTH,
        BREAKOUT_MAP_HEIGHT,
        breakout_background_map
    );

    set_sprite_tile(BALL_SPRITE, TILE_BALL);
    set_sprite_prop(BALL_SPRITE, 0x00u);
    set_sprite_tile(PADDLE_LEFT_SPRITE, TILE_PADDLE_LEFT);
    set_sprite_tile(PADDLE_MIDDLE_SPRITE, TILE_PADDLE_MIDDLE);
220→    set_sprite_tile(PADDLE_RIGHT_SPRITE, TILE_PADDLE_RIGHT);

    for (i = 0u; i < TRAIL_LENGTH; ++i) {
        set_sprite_tile((uint8_t)(TRAIL_SPRITE_BASE + i), TILE_BALL);
        /* OBP1 + lower priority so the live ball stays on top. */
        set_sprite_prop((uint8_t)(TRAIL_SPRITE_BASE + i), 0x11u);
        move_sprite((uint8_t)(TRAIL_SPRITE_BASE + i), 0u, 0u);
    }

    SPRITES_8x8;
230→    SHOW_BKG;
    SHOW_SPRITES;
    DISPLAY_ON;
}

static void initialize_game(void) {
    uint8_t i;

    paddle_x = PADDLE_INITIAL_X;
    ball_x = BALL_INITIAL_X;
240→    ball_y = BALL_INITIAL_Y;
    ball_vx = 1;
    ball_vy = -1;
    bricks_remaining = INITIAL_BRICK_COUNT;
    trail_count = 0u;

    for (i = 0u; i < TRAIL_LENGTH; ++i) {
        trail_x[i] = 0u;
        trail_y[i] = 0u;
        move_sprite((uint8_t)(TRAIL_SPRITE_BASE + i), 0u, 0u);
250→    }

    move_paddle(0);
    move_sprite(BALL_SPRITE, ball_x, ball_y);
